-- CREATE OR REPLACE VIEW cannot drop columns, and both functions return the view's row type.
DROP FUNCTION public.author_of_content(public.my_contents);
DROP FUNCTION public.author_of_concept(public.my_concepts);
DROP VIEW public.my_accounts;

-- Leaves out dg_account, which would show which accounts belong to one person, and metadata, which nothing uses yet.
CREATE VIEW public.my_accounts AS
SELECT
    id,
    name,
    platform,
    account_local_id,
    write_permission,
    active,
    agent_type
FROM public."PlatformAccount"
WHERE id IN (
    SELECT "LocalAccess".account_id FROM public."LocalAccess"
        JOIN public."SpaceAccess" USING (space_id)
        JOIN public.my_user_accounts() ON (account_uid = my_user_accounts)
    WHERE permissions >= 'partial'
    UNION
    SELECT id FROM public."PlatformAccount" WHERE dg_account = auth.uid()
);

-- Single-table views are writable, and writes run as the view owner, bypassing PlatformAccount's RLS.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.my_accounts FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.author_of_content(content public.my_contents)
RETURNS SETOF public.my_accounts STRICT STABLE
----
    END LOOP;
END;
$$;

-- Made ahead of public access, when clients without a login will read what is shared publicly. RLS decides which rows they see.
-- Space's policy shows anon no rows today. create-space runs a test query on Space with the caller's key, and refuses the call if it fails.
GRANT SELECT ON TABLE
public."Space",
public.concept_contributors,
public.content_contributors,
public.accounts_in_my_partial_spaces,
public.my_accounts,
public.my_concepts,
public.my_contents,
public.my_contents_with_embedding_openai_text_embedding_3_small_1536,
public.my_documents,
public.my_file_references,
public.my_groups,
public.my_pseudo_accounts,
public.my_resource_grants,
public.my_spaces
TO anon;

-- Clients read the views and never write through them.
REVOKE INSERT, UPDATE, DELETE ON TABLE
public.accounts_in_my_partial_spaces,
public.my_accounts,
public.my_concepts,
public.my_contents,
public.my_contents_with_embedding_openai_text_embedding_3_small_1536,
public.my_documents,
public.my_file_references,
public.my_groups,
public.my_pseudo_accounts,
public.my_resource_grants,
public.my_spaces
FROM authenticated;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON TABLE
public.accounts_in_my_partial_spaces,
public.my_resource_grants
FROM service_role;
